1	import { useEffect, useMemo, useRef, useState } from "react";
2	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
3	import { Button } from "@/components/ui/button";
4	import { Textarea } from "@/components/ui/textarea";
5	import { Badge } from "@/components/ui/badge";
6	import { MessageSquare, Send, Sparkles, Loader2, Trash2 } from "lucide-react";
7	
8	type Msg = { role: "user" | "assistant"; content: string };
9	
10	interface LearnChatProps {
11	  topicId: string;
12	  topicTitle: string;
13	  starterQuestions?: string[];
14	}
15	
16	const API_BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
17	const MAX_PERSISTED_MESSAGES = 40;
18	
19	function storageKey(topicId: string) {
20	  return `gameforge.learn.chat.${topicId}`;
21	}
22	
23	function isValidMsg(x: unknown): x is Msg {
24	  if (!x || typeof x !== "object") return false;
25	  const r = x as Record<string, unknown>;
26	  return (r.role === "user" || r.role === "assistant") && typeof r.content === "string";
27	}
28	
29	export function LearnChat({ topicId, topicTitle, starterQuestions = [] }: LearnChatProps) {
30	  const [messages, setMessages] = useState<Msg[]>([]);
31	  const [draft, setDraft] = useState("");
32	  const [loading, setLoading] = useState(false);
33	  const [error, setError] = useState<string | null>(null);
34	  const scrollRef = useRef<HTMLDivElement>(null);
35	
36	  // Load persisted history per topic.
37	  useEffect(() => {
38	    setError(null);
39	    setDraft("");
40	    try {
41	      const raw = localStorage.getItem(storageKey(topicId));
42	      const parsed = raw ? JSON.parse(raw) : [];
43	      if (Array.isArray(parsed)) {
44	        setMessages(parsed.filter(isValidMsg).slice(-MAX_PERSISTED_MESSAGES));
45	      } else {
46	        setMessages([]);
47	      }
48	    } catch {
49	      setMessages([]);
50	    }
51	  }, [topicId]);
52	
53	  useEffect(() => {
54	    try {
55	      const trimmed = messages.slice(-MAX_PERSISTED_MESSAGES);
56	      localStorage.setItem(storageKey(topicId), JSON.stringify(trimmed));
57	    } catch {/* ignore */}
58	  }, [messages, topicId]);
59	
60	  useEffect(() => {
61	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
62	  }, [messages, loading]);
63	
64	  const send = async (text: string) => {
65	    const trimmed = text.trim();
66	    if (!trimmed || loading) return;
67	    const next: Msg[] = [...messages, { role: "user", content: trimmed }];
68	    setMessages(next);
69	    setDraft("");
70	    setLoading(true);
71	    setError(null);
72	    try {
73	      const res = await fetch(`${API_BASE}/api/learn/chat`, {
74	        method: "POST",
75	        credentials: "include",
76	        headers: { "Content-Type": "application/json" },
77	        body: JSON.stringify({
78	          topicId,
79	          message: trimmed,
80	          history: messages.slice(-10),
81	        }),
82	      });
83	      if (!res.ok) {
84	        const body = await res.json().catch(() => ({}));
85	        throw new Error(body.error || `HTTP ${res.status}`);
86	      }
87	      const data = (await res.json()) as { reply: string };
88	      setMessages([...next, { role: "assistant", content: data.reply }]);
89	    } catch (err) {
90	      setError(err instanceof Error ? err.message : String(err));
91	    } finally {
92	      setLoading(false);
93	    }
94	  };
95	
96	  const clear = () => {
97	    setMessages([]);
98	    setError(null);
99	    try { localStorage.removeItem(storageKey(topicId)); } catch {/* ignore */}
100	  };
101	
102	  const showStarters = useMemo(() => messages.length === 0 && starterQuestions.length > 0, [messages, starterQuestions]);
103	
104	  return (
105	    <Card className="bg-card border-border" data-testid="learn-chat">
106	      <CardHeader className="pb-3">
107	        <div className="flex items-center justify-between gap-2">
108	          <CardTitle className="text-sm flex items-center gap-2">
109	            <MessageSquare className="h-4 w-4 text-primary" />
110	            Ask about this topic
111	            <Badge variant="outline" className="text-[10px] uppercase tracking-wider">Scoped</Badge>
112	          </CardTitle>
113	          {messages.length > 0 && (
